C3.push(()=>mcq(TAG.mix,b('Bi gatz-disoluzio guztiz disoziatu nahastean, zein da karga egiaztatzeko baldintza?','Al mezclar dos disoluciones de sales totalmente disociadas, ¿qué condición comprueba la carga?'),b('Katioien karga molarrak eta anioienak berdinak dira','La carga molar de los cationes es igual a la de los aniones'),[b('Katioi-mol guztiak anioi-mol guztien berdinak dira','Los moles totales de cationes son iguales a los de aniones'),b('Kontzentrazio guztiek batura 1 ematen dute','Todas las concentraciones suman 1'),b('Gatz bakoitzak disoluzioaren bolumen bera du','Cada sal tiene el mismo volumen de disolución')],b('Disoluzio elektroneutro batean, espezie positiboen eta negatiboen karga baliokide molarrak berdinak dira.','En una disolución electroneutra, las cargas molares equivalentes de las especies positivas y negativas son iguales.')));

/* ---------- U4: gasak ---------- */
function qGas(){const n=r(.5,3,2),T=pick([273,298,323,400]),V=pick([5,10,20]),P=n*.082*T/V;return nq(TAG.gas,b(`${V} L-ko ontzi batean ${fix(n,2)} mol gas ideal daude ${T} K-ean. Zein da presioa atm-tan?`,`${fix(n,2)} mol de gas ideal ocupa ${V} L a ${T} K. ¿Presión en atm?`),P,b(`PV=nRT; P=nRT/V=${fix(n,2)}·0,082·${T}/${V}=${fix(P,3)} atm.`,`PV=nRT; P=nRT/V=${fix(n,2)}·0,082·${T}/${V}=${fix(P,3)} atm.`),{label:'atm'});}
const C4=[()=>mcq(TAG.gas,b('Baldintza normaletan, 1 mol gas idealak gutxi gorabehera zer bolumen hartzen du?','En condiciones normales, ¿qué volumen ocupa aproximadamente 1 mol de gas ideal?'),b('22,4 L','22,4 L'),[b('1,00 L','1,00 L'),b('24,5 mL','24,5 mL'),b('100 L','100 L')],b('0 °C eta 1 atm-rako bolumen molarra ≈22,4 L/mol da; baldintza zehatzetan, erabili PV=nRT.','A 0 °C y 1 atm el volumen molar es ≈22,4 L/mol; con otras condiciones, aplica PV=nRT.')),()=>mcq(TAG.gas,b('Gas idealen nahaste batean % 12 bolumenekoa den osagaia…','En una mezcla de gases ideales, un componente al 12 % en volumen…'),b('% 12 mol du eta presio partziala 0,12·Ptot da','está al 12 % en moles y su presión parcial es 0,12·Ptot'),[b('% 12 masakoa da','está al 12 % en masa'),b('presio totala da','es la presión total'),b('bolumen molarra % 12 jaisten du','reduce el volumen molar un 12 %')],b('T eta P berean, gas ideal baten V proportzionala da n-rekin; beraz yᵢ = nᵢ/nT = Vᵢ/VT eta Daltonen Pi=yiPT.','A igual T y P, el volumen de un gas ideal es proporcional a n; por tanto yᵢ = nᵢ/nT = Vᵢ/VT y, por Dalton, Pi=yiPT.')),()=>mcq(TAG.gas,b('Gas bat urez asetuta dagoenean, zer adierazten du ur-lurrunaren presio partzialak?','Cuando un gas está saturado de agua, ¿qué determina la presión parcial del vapor de agua?'),b('Tenperatura horretako uraren lurrun-presioak','La presión de vapor del agua a esa temperatura'),[b('Gas lehorren presioak beti','Siempre la presión de los gases secos'),b('Uraren masa molarrak','La masa molar del agua'),b('Ontziaren bolumenak soilik','Solo el volumen del recipiente')],b('Asetasunean P(H₂O)=P*H₂O(T); gainerako gasen presio lehorra presio totaletik kentzen da.','En saturación P(H₂O)=P*H₂O(T); la presión seca restante se obtiene restando del total.'))];
U.push({id:'o4',short:b('Gasak','Gases'),title:b('Gas idealak, Dalton eta ur-lurruna','Gases ideales, Dalton y vapor de agua'),sub:b('Presioa, mol kopurua eta tenperatura lotu; nahasteen gas-konposizioa presio partzialetara pasa','Relacionar presión, moles y temperatura; convertir composición gaseosa en presiones parciales'),blocks:[
 ['p',b('Gas idealen ereduak gas-partikulen arteko interakzioak baztertzen ditu eta P, V, n eta T erlazionatzen ditu. Oreka-ariketetan, gas-nahasteak idealak direla jo ohi da. Tenperatura beti kelvinetan jarri. Baldintza normalen ohiko hitzarmena 0 °C eta 1 atm da, eta hor 1 mol gas ≈22,4 L; baldintzak bestelakoak badira, egoera-ekuazioa erabili.','El modelo de gas ideal desprecia las interacciones entre partículas y relaciona P, V, n y T. En problemas de equilibrio suele suponerse comportamiento ideal. La temperatura siempre se expresa en kelvin. La convención habitual de condiciones normales es 0 °C y 1 atm, donde 1 mol de gas ocupa ≈22,4 L; en otras condiciones se usa la ecuación de estado.')],
 ['f',{name:b('Gas idealen egoera-ekuazioa','Ecuación de estado de los gases ideales'),f:'P V = n R T',vars:[['P',b('presioa','presión'),'atm'],['V',b('bolumena','volumen'),'L'],['n',b('gas-molak','moles de gas'),'mol'],['R','0,082','atm·L·mol⁻¹·K⁻¹'],['T',b('tenperatura absolutua','temperatura absoluta'),'K']],use:b('Edozein egoera-bikote ezagututa geratzen den aldagaia kalkulatzeko; gas-nahasteetan n guztira gas-espezie guztiak zenbatu.','Para calcular una variable a partir de las otras; en mezclas, n total incluye todas las especies gaseosas.'),cond:b('T(K)=t(°C)+273,15. Erabili R=0,082 presioa atm-tan eta bolumena L-tan dagoenean.','T(K)=t(°C)+273,15. Usa R=0,082 si P está en atm y V en L.'),err:b('Ez erabili Celsius, ezta gas erreaktiboak bakarrik mol totaletan: inerteek presio osoa ere eragiten dute.','No uses Celsius ni omitas inertes de los moles totales: también contribuyen a la presión total.')}],
 ['f',{name:b('Daltonen legea','Ley de Dalton'),f:'P<sub>i</sub> = y<sub>i</sub>P<sub>T</sub> = '+frac('n<sub>i</sub>RT','V')+' &nbsp; · &nbsp; P<sub>T</sub> = ΣP<sub>i</sub>',vars:[['yᵢ',b('frakzio molarra = nᵢ/nT; gas idealetan bolumen-frakzioaren berdina','fracción molar = nᵢ/nT; en gases ideales equivale a la fracción en volumen'),''],['Pᵢ',b('i osagaiaren presio partziala','presión parcial del componente i'),'atm'],['PT',b('presio osoa, partzialen batura','presión total, suma de las parciales'),'atm']],use:b('Nahaste baten presio partzialak eta gas-konposizioa elkarrekin bihurtzeko.','Para relacionar presiones parciales y composición de una mezcla.'),cond:b('Gas ideala eta espezie gaseoso guztiak; mol-% = bolumen-% T eta P berean.','Mezcla de gases ideales; % molar = % volumen a igual T y P.')}],
 ['f',{name:b('Baldintza normalak','Condiciones normales'),f:'n = '+frac('V','22,4 L·mol⁻¹')+' &nbsp; (0 °C, 1 atm)',vars:[['V',b('baldintza normaletako gas-bolumena','volumen de gas en condiciones normales'),'L']],use:b('Bolumenetik molak lortzeko, gasa c.n.-tan dagoenean. Beste baldintzetan PV=nRT.','Para convertir volumen en moles si el gas está en c.n.; en otras condiciones, PV=nRT.'),err:b('Baldintza normalen balioa ez aplikatu tenperatura edo presioa bestelakoa denean.','No uses el volumen de c.n. si la temperatura o presión es distinta.')}],
 ['steps',[b('Idatzi osagai bakoitzaren molak; bolumen-ehunekoak frakzio molarrak dira gas idealetan.','Escribe los moles de cada componente; en gases ideales los porcentajes en volumen son fracciones molares.'),b('Kendu kondentsagarriaren presio partziala asetasun-datua badago: P(H₂O)=P*bap(T).','Resta la presión parcial del condensable si hay un dato de saturación: P(H₂O)=P*vap(T).'),b('Kalkulatu gainerako presio partzialak Daltonen legearekin; Ptotal haien batura da.','Calcula las demás presiones parciales por Dalton; Ptotal es la suma de las parciales.'),b('Egin egoera-ekuazioa: T kelvinetan, unitate bateragarriak eta gas inerte guztiak barruan.','Aplica la ecuación de estado: T en kelvin, unidades compatibles y todos los gases inertes incluidos.')],b('Gas-ariketen kalkulu-ordena','Orden de cálculo en problemas de gases')],
 ['ex',{title:b('Ur-lurrunez asetutako gas-nahastea','Mezcla gaseosa saturada de vapor de agua'),q:b('Ontzi batean 0,500 mol CO eta 1,00 mol N₂ daude 300 K eta 10,0 L-tan. Kalkulatu PT eta P(CO). Ondoren, suposatu nahasteak ur-lurruna ere baduela eta P*(H₂O)=26,8 mmHg dela: zein da ur-lurrunaren mol-frakzioa PT=1,00 atm bada?','Un recipiente contiene 0,500 mol de CO y 1,00 mol de N₂ a 300 K y 10,0 L. Calcula PT y P(CO). Después, supone que la mezcla también contiene vapor de agua y que P*(H₂O)=26,8 mmHg: ¿cuál es la fracción molar del vapor si PT=1,00 atm?'),steps:[b('nT=1,500 mol. PT=nRT/V=1,500·0,082·300/10,0=<b>3,69 atm</b>.','nT=1,500 mol. PT=nRT/V=1,500·0,082·300/10,0=<b>3,69 atm</b>.'),b('y(CO)=0,500/1,500=1/3; P(CO)=yPT=<b>1,23 atm</b>.','y(CO)=0,500/1,500=1/3; P(CO)=yPT=<b>1,23 atm</b>.'),b('Asetasuneko beste kasuan y(H₂O)=P*/PT=(26,8/760)/1,00=<b>0,0353</b>.','En el caso de saturación, y(H₂O)=P*/PT=(26,8/760)/1,00=<b>0,0353</b>.')],res:b('Lehen nahastea: PT=3,69 atm, P(CO)=1,23 atm. Asetutako bigarren kasuan y(H₂O)=0,0353.','Primera mezcla: PT=3,69 atm, P(CO)=1,23 atm. En el segundo caso saturado y(H₂O)=0,0353.'),check:b('Lehen kasuan P(CO)+P(N₂)=3,69 atm eta presio partzialak PT baino txikiagoak dira.','En el primer caso P(CO)+P(N₂)=3,69 atm y cada presión parcial es menor que PT.') }],
 ['warn',b('Gas asearen adierazpenak P(H₂O)=P* ezartzen du, ez ur-lurrunaren ehunekoa. Ehunekoa kalkulatzeko Ptotal ezagutu behar da. Gainerako osagaiak lehor daudela esaten bada, ez gehitu H₂O berriro.','La saturación fija P(H₂O)=P*, no el porcentaje de vapor. Para obtener el porcentaje hace falta Ptotal. Si se especifica una composición seca, no vuelvas a añadir H₂O.')],
 ['exam',b(`Gasak eta Dalton agertzen dira nahastea prestatzean eta presio osoa kalkulatzean: ${ax('2022-23-o',1,'2022-23 ohikoa','2022-23 ohikoa')}. Ur-lurrun asearen adibide argia: ${ax('2020-21-e',1,'2020-21 ez-ohikoa','2020-21 ez-ohikoa')}.`,`Los gases y Dalton aparecen al preparar mezclas y calcular la presión total: ${ax('2022-23-o',1,'2022-23 ordinaria','2022-23 ohikoa')}. Un ejemplo directo de vapor de agua saturado: ${ax('2020-21-e',1,'2020-21 extraordinaria','2020-21 ez-ohikoa')}.`)],
 ['terms',[['gas ideala','gas ideal'],['baldintza normalak','condiciones normales'],['presio partziala','presión parcial'],['presio osoa','presión total'],['frakzio molarra','fracción molar'],['gas geldoa','gas inerte'],['ur-lurrun ase','vapor de agua saturado']]]],
 quiz:()=>[qGas(),qGas(),qGas(),qGas(),qGas(),...C4.map(f=>f())],cards:[[b('Gas idealen legea','Ley de gases ideales'),'PV=nRT; T K-tan'],[b('R atm·L unitateetan','R en unidades atm·L'),'0,082 atm·L·mol⁻¹·K⁻¹'],[b('Baldintza normalak','Condiciones normales'),b('0 °C eta 1 atm; Vm≈22,4 L/mol.','0 °C y 1 atm; Vm≈22,4 L/mol.')],[b('Daltonen legea','Ley de Dalton'),'Pᵢ=yᵢPT; PT=ΣPᵢ'],[b('Gas idealetan bolumen-%','% en volumen en gases ideales'),b('Mol-%-aren berdina da.','Coincide con el % molar.')],[b('Gas asearen ur-lurruna','Vapor de agua en un gas saturado'),b('P(H₂O)=P*vap(T).','P(H₂O)=P*vap(T).')]]});

/* Add a Dalton question with a new task type beyond PV=nRT calculations. */
C4.push(()=>mcq(TAG.gas,b('Bi osagaiko gas idealetan y(A)=0,35 bada, zer da P(A)?','En una mezcla ideal binaria, si y(A)=0,35, ¿cuánto vale P(A)?'),b('0,35·P<sub>T</sub>','0,35·P<sub>T</sub>'),[b('P<sub>T</sub>/0,35','P<sub>T</sub>/0,35'),b('P<sub>T</sub>−0,35','P<sub>T</sub>−0,35'),b('0,65·P<sub>T</sub>','0,65·P<sub>T</sub>')],b('Daltonen legearen arabera presio partziala frakzio molarra bider presio osoa da.','Por la ley de Dalton, la presión parcial es la fracción molar multiplicada por la presión total.')));

/* ---------- U5: algebra, logarithms, approximation and numerical roots ---------- */
function qLog(){const p=pick([2,3,4,5,6]),c=Math.pow(10,-p);return nq(TAG.math,b(`pH = ${p}, beraz [H₃O⁺] = ? (mol/L)`,`pH = ${p}; ¿cuánto vale [H₃O⁺] (mol/L)?`),c,b('[H₃O⁺]=10<sup>−pH</sup> = 10<sup>−'+p+'</sup> M.','[H₃O⁺]=10<sup>−pH</sup> = 10<sup>−'+p+'</sup> M.'),{abs:c*.01,label:'mol/L'});}
function qQuadratic(){const Ka=pick([1e-4,1e-5,2e-5]),C=pick([.05,.1,.2]),x=(-Ka+Math.sqrt(Ka*Ka+4*Ka*C))/2;return nq(TAG.math,b(`Azido ahul baterako x²/(C−x)=Kₐ; Kₐ=${num(Ka,2)}, C=${fix(C,2)} M. Kalkulatu x (M) ekuazio koadratiko zehatzez.`,`Para un ácido débil, x²/(C−x)=Kₐ; Kₐ=${num(Ka,2)}, C=${fix(C,2)} M. Calcula x (M) resolviendo la cuadrática exactamente.`),x,b(`x²+Kₐx−KₐC=0; erro positiboa x=(-Kₐ+√(Kₐ²+4KₐC))/2=${num(x,3)} M.`,`x²+Kₐx−KₐC=0; la raíz positiva x=(-Kₐ+√(Kₐ²+4KₐC))/2=${num(x,3)} M.`),{label:'M'});}
const C5=[()=>mcq(TAG.math,b('pH-ren definizioa zein da?','¿Cuál es la definición de pH?'),b('pH=−log₁₀[H₃O⁺] (kontzentrazioa M-tan)','pH=−log₁₀[H₃O⁺] (concentración en M)'),[b('pH=log₁₀[H₃O⁺]','pH=log₁₀[H₃O⁺]'),b('pH=1/[H₃O⁺]','pH=1/[H₃O⁺]'),b('pH=−ln[OH⁻]','pH=−ln[OH⁻]')],b('Logaritmo hamartarra erabiltzen da; alderantziz [H₃O⁺]=10⁻pH.','Se usa el logaritmo decimal; la relación inversa es [H₃O⁺]=10⁻pH.')),()=>mcq(TAG.math,b('Kalkulatutako x/C = 0,032 bada, x≪C hurbilketa onargarria al da % 5eko arauaren arabera?','Si el x/C calculado es 0,032, ¿es válida la aproximación x≪C según la regla del 5 %?'),b('Bai; erabili den hasierako kontzentrazioaren % 3,2 baino ez da','Sí; solo es el 3,2 % de la concentración inicial'),[b('Ez; % 32 baita','No; es el 32 %'),b('Ez; x beti zehatza izan behar da','No; x siempre debe ser exacta'),b('Bai, x/C edozein izanda ere','Sí, independientemente de x/C')],b('Gutxitutako kantitatea hasierakoaren % 5 baino txikiagoa bada, hurbilketa onargarria da; kalkulua amaitzean egiaztatu.','La aproximación es aceptable si el cambio es menor del 5 % del valor inicial; compruébalo al terminar el cálculo.')),()=>mcq(TAG.math,b('Bisection metodoak zer eskatzen du erroa aurkitzeko?','¿Qué requiere la bisección para encontrar una raíz?'),b('f-ren zeinu desberdineko muturrak dituen tarte itxia','Un intervalo cerrado cuyos extremos tienen signos opuestos de f'),[b('Bigarren mailako ekuazioa bakarrik','Solo una ecuación de segundo grado'),b('Erroa zehazki aurrez jakitea','Conocer de antemano la raíz exacta'),b('f-ren balio positiboak soilik','Solo valores positivos de f')],b('Tarteko erdiko puntua hartu eta zeinu-aldaketa duen erdia gordetzen da; jarraitutasunak erroaren inguraketa bermatzen du.','Se prueba el punto medio y se conserva la mitad que contiene el cambio de signo; con continuidad, el intervalo acota la raíz.'))];
U.push({id:'o5',short:b('Matematika tresnak','Herramientas matemáticas'),title:b('Logaritmoak, ekuazioak eta erroak zenbakiz ebaztea','Logaritmos, ecuaciones y resolución numérica de raíces'),sub:b('pH, notazio zientifikoa, ekuazio koadratikoak, hurbilketak, bisekzioa eta zifra esanguratsuak','pH, notación científica, cuadráticas, aproximaciones, bisección y cifras significativas'),blocks:[
 ['p',b('Kimikan kalkuluak unitateekin hasi eta amaitzen dira. Notazio zientifikoa erabiltzeak magnitude handiak eta txikiak irakurgarri egiten ditu; logaritmoek pH bezalako eskalak laburtzen dituzte. Ekuazio koadratikoetan bi erro ager daitezke, baina kontzentrazio fisikoak positiboak dira eta muga materialak bete behar dituzte. Maila handiagoko ekuazioetan, erroa zenbakiz bilatu eta tarte fisikoaren barruan dagoela egiaztatu.','Los cálculos químicos empiezan y terminan con unidades. La notación científica hace legibles magnitudes muy grandes o pequeñas; los logaritmos comprimen escalas como el pH. Las ecuaciones cuadráticas pueden dar dos raíces, pero las concentraciones físicas son positivas y deben respetar los límites materiales. Para ecuaciones de grado superior, busca la raíz numéricamente y comprueba que está dentro del intervalo físico.')],
 ['f',{name:b('pH eta pOH','pH y pOH'),f:'pH = −log<sub>10</sub>[H<sub>3</sub>O<sup>+</sup>] &nbsp; · &nbsp; pOH = −log<sub>10</sub>[OH<sup>−</sup>] &nbsp; · &nbsp; pH+pOH=14 (25 °C)',vars:[['[H₃O⁺], [OH⁻]',b('kontzentrazio molarrak','concentraciones molares'),'mol·L⁻¹'],['pH, pOH',b('unitaterik gabeko logaritmo-neurriak','magnitudes logarítmicas sin unidad'),'']],use:b('Ur-disoluzioetako azidotasuna eta basikotasuna adierazteko; [H₃O⁺]=10⁻pH.','Para expresar acidez y basicidad en agua; [H₃O⁺]=10⁻pH.'),cond:b('pH+pOH=14,00 25 °C-an Kw=10⁻¹⁴ denean. Kontzentrazioak M-tan adierazi behar dira.','pH+pOH=14,00 a 25 °C, con Kw=10⁻¹⁴. Las concentraciones se expresan en M.'),err:b('pH bat unitaterik gabea da eta logaritmo hamartarra erabiltzen du; 10eko berretzailearen zeinua ez irauli.','El pH no tiene unidades y usa logaritmo decimal; no inviertas el signo del exponente de 10.')}],
 ['f',{name:b('Ekuazio koadratikoa eta erro fisikoa','Ecuación cuadrática y raíz física'),f:'ax² + bx + c = 0 &nbsp;→&nbsp; x = '+frac('−b ± √(b²−4ac)','2a'),vars:[['a,b,c',b('ekuazioaren koefizienteak','coeficientes de la ecuación'),''],['x',b('aldagai ezezaguna','variable incógnita'),'']],use:b('Oreka-adierazpen batetik x² motako ekuazioa lortzen denean; aztertu diskriminatzailea eta bi erroak.','Cuando una expresión de equilibrio produce una ecuación cuadrática; evalúa el discriminante y las dos raíces.'),cond:b('Aukeratu muga fisikoak betetzen dituen erroa: n≥0, 0≤x≤C edo 0≤ξ≤ξmax.','Elige la raíz que cumple los límites físicos: n≥0, 0≤x≤C o 0≤ξ≤ξmax.'),err:b('Ez aukeratu erro positiboa automatikoki: erro fisikoak beste baldintza batzuk ere bete behar ditu.','No elijas automáticamente una raíz por ser positiva: debe satisfacer también las demás restricciones físicas.')}],
 ['f',{name:b('Hurbilketa eta % 5eko araua','Aproximación y regla del 5 %'),f:b('x ≪ C &nbsp; bada &nbsp; C−x ≈ C &nbsp; baina egiaztatu &nbsp; '+frac('x','C')+'·100 % < 5 %','si x ≪ C &nbsp; entonces &nbsp; C−x ≈ C &nbsp; pero verifica &nbsp; '+frac('x','C')+'·100 % < 5 %'),vars:[['x',b('erreakzionatutako edo disoziatutako kantitatea','cantidad reaccionada o disociada'),'M'],['C',b('hasierako kontzentrazioa','concentración inicial'),'M']],use:b('Ekuazioa sinplifikatzeko azido/base ahul oso ahuletan, edo ezezagun bat kontzentrazio handi bati kentzen zaionean.','Para simplificar ecuaciones en ácidos o bases muy débiles, o cuando se resta una incógnita pequeña a una concentración grande.'),cond:b('Hurbildu ondoren egiaztatu x/C·100<5%; bestela, ebatzi ekuazio zehatza.','Tras aproximar, comprueba x/C·100<5 %; si no, resuelve la ecuación exacta.'),err:b('Ez hartu % 5eko araua egiatzat frogatu gabe.','No des por válida la regla del 5 % sin verificarla.')}],
 ['f',{name:b('Notazio zientifikoa eta logaritmoak','Notación científica y logaritmos'),f:'N = a·10<sup>n</sup> &nbsp; (1 ≤ |a| &lt; 10) &nbsp; · &nbsp; log(ab)=log a + log b',vars:[['a',b('mantisa edo koefizientea','mantisa o coeficiente'),''],['n',b('10en berretzaile osoa','exponente entero de 10'),''],['log',b('logaritmo hamartarra, 10 oinarrikoa','logaritmo decimal, de base 10'),'']],use:b('Oso kontzentrazio txiki/handiak idazteko eta pH moduko eskaletan. Alderantzizko erlazioa: log x = y ⇔ x=10ʸ.','Para escribir concentraciones muy pequeñas o grandes y escalas como pH. Relación inversa: log x = y ⇔ x=10ʸ.'),cond:b('Zenbakiak biribildu amaieran bakarrik; emaitzan datuen zifra esanguratsuak gorde eta unitateak adierazi.','Redondea solo al final; conserva en el resultado las cifras significativas justificadas por los datos e indica unidades.'),err:b('10⁻³ = 0,001 da, ez 0,003. pH kalkulatzeko log₁₀ erabili, ln ez.','10⁻³ = 0,001, no 0,003. Para el pH usa log₁₀, no ln.')}],
 ['steps',[b('Ekuazioa antolatu: f(x)=0 eta zehaztu x-ren tarte fisikoa.','Ordena la ecuación como f(x)=0 y determina el intervalo físico de x.'),b('Aukeratu [a,b] tarte bat, non f(a) eta f(b) zeinu desberdinekoak diren.','Elige un intervalo [a,b] en el que f(a) y f(b) tengan signos opuestos.'),b('Kalkulatu erdiko puntua m=(a+b)/2. Erroarekin alde berean zeinua duen muturra m-rekin ordezkatu.','Calcula el punto medio m=(a+b)/2. Sustituye por m el extremo cuyo f tiene el mismo signo que f(m).'),b('Errepikatu erro-tartea nahi den zehaztasunera arte; kalkulagailuko SOLVE erabiliz gero ere egiaztatu erro fisikoa eta unitateak.','Repite hasta lograr la precisión deseada; incluso si usas SOLVE, comprueba que la raíz es física y las unidades correctas.')],b('Bisekzioa eta SOLVE moduaren egiaztapena','Bisección y comprobación con SOLVE')],
 ['lab','bisekzioa',{}],['ex',{title:b('Azido ahula: ekuazio zehatza eta hurbilketa','Ácido débil: ecuación exacta y aproximación'),q:b('Azido monoprotiko ahul baten C=0,100 M eta Ka=1,80×10⁻⁵ dira. Kalkulatu [H₃O⁺] eta pH zehazki; ondoren egiaztatu % 5eko araua.','Un ácido monoprótico débil tiene C=0,100 M y Ka=1,80×10⁻⁵. Calcula exactamente [H₃O⁺] y el pH; después comprueba la regla del 5 %.'),steps:[b('Ka=x²/(C−x) → x²+Ka·x−Ka·C=0.','Ka=x²/(C−x) → x²+Ka·x−Ka·C=0.'),b('Erro positiboa: x=(-Ka+√(Ka²+4KaC))/2 = <b>1,333×10⁻³ M</b>.','Raíz positiva: x=(-Ka+√(Ka²+4KaC))/2 = <b>1,333×10⁻³ M</b>.'),b('x/C·100=1,33 % <5 %, beraz C−x≈C hurbilketa onargarria da. pH=−log₁₀(1,333×10⁻³)=<b>2,875</b>.','x/C·100=1,33 % <5 %, así que C−x≈C es una aproximación válida. pH=−log₁₀(1,333×10⁻³)=<b>2,875</b>.')],res:b('[H₃O⁺]=1,33×10⁻³ M; pH=2,875; % 5eko araua betetzen da.','[H₃O⁺]=1,33×10⁻³ M; pH=2,875; se cumple la regla del 5 %.') }],
 ['warn',b('Kalkulagailuko SOLVE edo saiakera bidezko emaitzek erro bat ematen dute, ez zertan erro kimiko zuzena. Egiaztatu f(x)≈0, kontzentrazio/masa guztiak ez-negatiboak direla eta emaitza datuen zehaztasunarekin bat datorrela.','SOLVE o el tanteo numérico devuelven una raíz, que no tiene por qué ser la raíz química correcta. Comprueba f(x)≈0, que todas las concentraciones y masas sean no negativas y que el resultado respete la precisión de los datos.')],
 ['exam',b(`Ekuazioak ebaztea eta emaitzaren koherentzia egiaztatzea erabiltzen dira kontzentrazio-ariketetan eta problema guztietan. Adibidea: ${ax('2019-20-e',10,'2019-20 ez-ohikoa','2019-20 ez-ohikoa')}.`,`Resolver ecuaciones y comprobar la coherencia del resultado se aplica a concentraciones y a todos los problemas. Ejemplo: ${ax('2019-20-e',10,'2019-20 extraordinaria','2019-20 ez-ohikoa')}.`)],
 ['terms',[['pH','pH-a'],['logaritmo hamartarra','logaritmo decimal'],['notazio zientifikoa','notación científica'],['erro fisikoa','raíz física'],['bisekzioa','bisección'],['hurbilketa','aproximación'],['zifra esanguratsuak','cifras significativas'],['koherentzia','coherencia']]]],
 quiz:()=>[qLog(),qLog(),qQuadratic(),qQuadratic(),...pickN(C5,4).map(f=>f())],cards:[[b('pH-ren formula','Fórmula del pH'),'pH=−log₁₀[H₃O⁺]'],[b('pH-tik [H₃O⁺]-ra','De pH a [H₃O⁺]'),'[H₃O⁺]=10<sup>−pH</sup>'],[b('Ekuazio koadratikoaren erroak','Raíces de la cuadrática'),'x=(-b±√(b²−4ac))/(2a)'],[b('% 5eko araua','Regla del 5 %'),b('Egiaztatu x/C·100<5; ez hartu aurrez frogatutzat.','Comprueba x/C·100<5; no la des por hecha.')],[b('Bisekzioan urrats bakoitza','Cada paso de bisección'),b('Erdiko puntua kalkulatu eta f-ren zeinu-aldaketa gordetzen duen erdia aukeratu.','Calcula el punto medio y conserva la mitad que mantiene el cambio de signo de f.')],[b('Emaitza egiaztatzea','Comprobación del resultado'),b('Ekuazioan ordezkatu, muga fisikoak eta unitateak egiaztatu.','Sustituye en la ecuación y comprueba límites físicos y unidades.')]]});

/* Fix two exam-reference blocks whose Basque text had been supplied as Spanish. */
U.find(u=>u.id==='o1').blocks[6][1]=b('Erreaktibo mugatzailea, purutasuna eta mol-erlazioak dira oinarria. Azterketetako adibideak: erreaktibo mugatzailea eta produktu teorikoa kalkulatzea, hidratoak eta purutasuna barne.','La base es identificar el reactivo limitante y aplicar pureza y relaciones molares. En los exámenes aparecen cálculos de reactivo limitante y producto teórico, también con hidratos y reactivos impuros.');
U.find(u=>u.id==='o3').blocks[6][1]=b('Masa, bolumena eta disoziazio-erlazioak uztartzea funtsezkoa da. Kontzentrazio-urratsak disoluzioak prestatzean ageri dira; gas-nahasteen osaera ere mol-balantzez kalkulatzen da.','Es esencial combinar masa, volumen y relaciones de disociación. Los pasos de concentración aparecen al preparar disoluciones; la composición de mezclas gaseosas también se obtiene mediante balances molares.');
U.find(u=>u.id==='o4').blocks[5][1].q.es=U.find(u=>u.id==='o4').blocks[5][1].q.es.replace('Después, supone que','Después, supón que');

