const X=[
 {id:'O-01',lvl:0,skill:b('Mol-kalkulua','Cálculo de moles'),title:b('Sodio kloruroaren lagina','Muestra de cloruro de sodio'),q:b('11,70 g NaCl lagin. M(NaCl)=58,44 g/mol. Kalkulatu NaCl molak.','Muestra de 11,70 g de NaCl. M(NaCl)=58,44 g/mol. Calcula los moles de NaCl.'),parts:[{q:b('n(NaCl) (mol)','n(NaCl) (mol)'),ans:0.2002,tol:.01}],hints:[b('Erabili n=m/M.','Usa n=m/M.'),b('Ziurtatu g unitatea masa molarrarekin ezabatzen dela.','Comprueba que la unidad g se cancela con la masa molar.')],sol:[b('n=11,70 g/(58,44 g·mol⁻¹)=0,2002 mol.','n=11,70 g/(58,44 g·mol⁻¹)=0,2002 mol.')],res:'0,2002 mol NaCl',check:b('Masa molarrarekin biderkatuz: 0,2002·58,44≈11,70 g.','Al multiplicar por la masa molar: 0,2002·58,44≈11,70 g.'),errs:b('Masa molarra zatitu beharrean biderkatzea.','Multiplicar por la masa molar en lugar de dividir.')},
 {id:'O-02',lvl:0,skill:b('Mugatzailea eta produktu teorikoa','Limitante y producto teórico'),title:b('Aluminio kloruroaren sintesia','Síntesis de cloruro de aluminio'),q:b('2Al+3Cl₂→2AlCl₃. 5,40 g Al eta 10,65 g Cl₂ erreakzionatzen dute. M(Al)=26,98, M(Cl₂)=70,90, M(AlCl₃)=133,33 g/mol.','2Al+3Cl₂→2AlCl₃. Reaccionan 5,40 g de Al y 10,65 g de Cl₂. M(Al)=26,98, M(Cl₂)=70,90, M(AlCl₃)=133,33 g/mol.'),parts:[{q:b('Mugatzailea: idatzi 1 Al-rako edo 2 Cl₂-rako','Limitante: escribe 1 para Al o 2 para Cl₂'),ans:2,abs:0.01},{q:b('AlCl₃ teorikoaren kantitatea (mol)','Cantidad teórica de AlCl₃ (mol)'),ans:.100,tol:.01},{q:b('AlCl₃-ren masa teorikoa (g)','Masa teórica de AlCl₃ (g)'),ans:13.352,tol:.01}],hints:[b('Bi masak moletara pasa.','Convierte ambas masas a moles.'),b('Alderatu n/ν.','Compara n/ν.')],sol:[b('n(Al)=5,40/26,98=0,200 mol; n(Cl₂)=10,65/70,90=0,150 mol.','n(Al)=5,40/26,98=0,200 mol; n(Cl₂)=10,65/70,90=0,150 mol.'),b('n/ν: Al 0,100; Cl₂ 0,0500 mol. Cl₂ mugatzailea da (2). ξmax=0,0500 mol.','n/ν: Al 0,100; Cl₂ 0,0500 mol. Cl₂ es el limitante (2). ξmax=0,0500 mol.'),b('n(AlCl₃)=2ξ=0,10014 mol; masa=0,10014·133,33=<b>13,35 g</b>.','n(AlCl₃)=2ξ=0,10014 mol; masa=0,10014·133,33=<b>13,35 g</b>.')],res:'Cl₂ mugatzailea; 0,10014 mol; 13,35 g',check:b('Cl₂-ren 0,1502 mol guztiak kontsumitzeko Al 0,1001 mol behar dira; Al 0,2001 mol zegoen.','Para consumir 0,1502 mol de Cl₂ se necesitan 0,1001 mol de Al; había 0,2001 mol.'),errs:b('Masa-erlazioak koefizienteetatik zuzenean ondorioztatzea.','Inferir directamente relaciones de masas a partir de los coeficientes.')},
 {id:'O-03',lvl:1,skill:b('Hidratoa','Hidrato'),title:b('Kristalizazio-ura bereizi','Separar el agua de cristalización'),q:b('12,50 g CuSO₄·5H₂O berotzean anhidroa geratzen da. M(CuSO₄)=159,61; M(CuSO₄·5H₂O)=249,68 g/mol. Kalkulatu CuSO₄-ren masa eta kendutako uraren masa.','Al calentar 12,50 g de CuSO₄·5H₂O queda la sal anhidra. M(CuSO₄)=159,61; M(CuSO₄·5H₂O)=249,68 g/mol. Calcula la masa de CuSO₄ y la masa de agua retirada.'),parts:[{q:b('CuSO₄ masa (g)','Masa de CuSO₄ (g)'),ans:7.991,tol:.005},{q:b('H₂O masa (g)','Masa de H₂O (g)'),ans:4.509,tol:.005}],hints:[b('Hidrato-molak kalkulatu formula osoaren masa molarrarekin.','Calcula los moles de hidrato con la masa molar completa.'),b('Mol bakoitzak 1 mol CuSO₄ eta 5 mol ur dauzka.','Cada mol contiene 1 mol de CuSO₄ y 5 mol de agua.')],sol:[b('n(hidratoa)=12,50/249,68=0,050064 mol.','n(hidrato)=12,50/249,68=0,050064 mol.'),b('n(CuSO₄)=0,050064 mol; m=0,050064·159,61=<b>7,991 g</b>.','n(CuSO₄)=0,050064 mol; m=0,050064·159,61=<b>7,991 g</b>.'),b('Uraren masa diferentziaz: 12,50−7,991=<b>4,509 g</b>.','La masa de agua es la diferencia: 12,50−7,991=<b>4,509 g</b>.')],res:'7,991 g CuSO₄; 4,509 g H₂O',check:b('Bi masen batura 12,50 g da, hasierako laginaren masa.','La suma de ambas masas es 12,50 g, la masa inicial.'),errs:b('Hidratoaren formula-masa osoa ez erabiltzea edo 5 ur molek eragiten dutela ahaztea.','No usar la masa fórmula completa del hidrato u olvidar las cinco moléculas de agua.')},
 {id:'O-04',lvl:1,skill:b('Diluzioa','Dilución'),title:b('Stocketik disoluzio diluitua','Disolución diluida desde una disolución madre'),q:b('0,800 M NaOH stocketik 250,0 mL 0,0800 M disoluzio prestatu behar dira. Zein stock-bolumen hartu behar da?','Se preparan 250,0 mL de NaOH 0,0800 M a partir de una disolución madre 0,800 M. ¿Qué volumen de stock se necesita?'),parts:[{q:b('V₁ (mL)','V₁ (mL)'),ans:25,tol:.005}],hints:[b('Diluzioaren aurretik eta ondoren NaOH mol-kopurua berdina da.','Los moles de NaOH son iguales antes y después de diluir.'),b('C₁V₁=C₂V₂.','C₁V₁=C₂V₂.')],sol:[b('V₁=C₂V₂/C₁=0,0800·250,0/0,800=<b>25,0 mL</b>.','V₁=C₂V₂/C₁=0,0800·250,0/0,800=<b>25,0 mL</b>.'),b('Hartu 25,0 mL stock-disoluziotik eta osatu urarekin 250,0 mL-ko azken bolumenera.','Toma 25,0 mL de stock y completa con agua hasta 250,0 mL de volumen final.')],res:'25,0 mL stock',check:b('Diluzio-faktorea 10 da; stock-bolumena azken bolumenaren hamarrena da.','El factor de dilución es 10; el volumen de stock es una décima parte del volumen final.'),errs:b('250 mL ur gehitu eta bolumen finala 250 mL dela suposatzea.','Añadir 250 mL de agua y suponer que ese es el volumen final.')},
 {id:'O-05',lvl:1,skill:b('Gas ideala eta Dalton','Gas ideal y Dalton'),title:b('Presio osoa eta osagaien proportzioak','Presión total y proporciones de los componentes'),q:b('0,400 mol CO, 0,100 mol H₂O(g) eta 0,500 mol Ar 10,0 L-ko ontzian daude 300 K-ean. Kalkulatu PT, P(CO) eta Ar-ren bolumen-ehunekoa.','0,400 mol de CO, 0,100 mol de H₂O(g) y 0,500 mol de Ar están en un recipiente de 10,0 L a 300 K. Calcula PT, P(CO) y el porcentaje en volumen de Ar.'),parts:[{q:'PT (atm)',ans:2.46,tol:.01},{q:b('P(CO) (atm)','P(CO) (atm)'),ans:.984,tol:.01},{q:b('Ar bolumen-%','% en volumen de Ar'),ans:50,tol:.01}],hints:[b('nT = espezie gaseoso guztien molen batura.','nT es la suma de los moles de todas las especies gaseosas.'),b('Dalton: Pi=(ni/nT)PT; gasetan mol-%=bolumen-%.','Dalton: Pi=(ni/nT)PT; en gases % molar = % volumen.')],sol:[b('nT=0,400+0,100+0,500=1,000 mol. PT=nRT/V=1·0,082·300/10,0=<b>2,46 atm</b>.','nT=0,400+0,100+0,500=1,000 mol. PT=nRT/V=1·0,082·300/10,0=<b>2,46 atm</b>.'),b('P(CO)=0,400·2,46=<b>0,984 atm</b>.','P(CO)=0,400·2,46=<b>0,984 atm</b>.'),b('y(Ar)=0,500/1,000; bolumen-%=<b>50,0 %</b>.','y(Ar)=0,500/1,000; % en volumen=<b>50,0 %</b>.')],res:'2,46 atm; 0,984 atm; 50,0 % Ar',check:b('Presio partzialen batura 2,46 atm da: CO 0,984; H₂O 0,246; Ar 1,230 atm.','La suma de presiones parciales es 2,46 atm: CO 0,984; H₂O 0,246; Ar 1,230 atm.'),errs:b('Gas inertea presio osotik kentzea.','Excluir el gas inerte de la presión total.')},
 {id:'O-06',lvl:2,skill:b('Hidratoa, purutasuna eta molalitatea','Hidrato, pureza y molalidad'),title:b('CaCl₂-disoluzioa bi gatzetatik','Disolución de CaCl₂ desde dos sales'),q:b('2019-20ko ariketaz bestelako datuekin: prestatu 2,00 L CaCl₂ 0,150 M disoluzioa 10,0 g CaCl₂·2H₂O eta CaCl₂ anhidro komertziala (% 75) erabiliz. ρ=1,04 g/mL; M(CaCl₂)=111,0; M(hidratoa)=147,0 g/mol. Kalkulatu gatz komertziala (g) eta CaCl₂-ren molalitatea.','Con datos distintos del ejercicio de 2019-20: prepara 2,00 L de CaCl₂ 0,150 M con 10,0 g de CaCl₂·2H₂O y CaCl₂ anhidro comercial al 75 %. ρ=1,04 g/mL; M(CaCl₂)=111,0; M(hidrato)=147,0 g/mol. Calcula la masa de sal comercial y la molalidad de CaCl₂.'),parts:[{q:b('Gatz anhidro komertziala (g)','Sal anhidra comercial (g)'),ans:34.33,tol:.01},{q:b('Molalitatea (mol/kg)','Molalidad (mol/kg)'),ans:.1472,tol:.01}],hints:[b('Helburuko CaCl₂ molak kalkulatu eta hidratoak emandakoak kendu.','Calcula los moles objetivo de CaCl₂ y resta los aportados por el hidrato.'),b('Purutasuna zatitzailea da gatz komertzialaren masa lortzeko.','La pureza se usa para dividir y obtener la masa comercial.'),b('Disoluzioaren masa dentsitatez; disolbatzailearen masa kenduz lortu.','Obtén la masa de disolución con la densidad y resta para hallar la masa de disolvente.')],sol:[b('n helburua=0,150·2,00=0,300 mol; hidratoak 10,0/147=0,06803 mol ematen ditu. Falta=0,23197 mol.','n objetivo=0,150·2,00=0,300 mol; el hidrato aporta 10,0/147=0,06803 mol. Faltan=0,23197 mol.'),b('Masa CaCl₂ purua=0,23197·111=25,75 g; %75eko masa komertziala=25,75/0,75=<b>34,3 g</b>.','Masa CaCl₂ pura=0,23197·111=25,75 g; masa comercial al 75 %=25,75/0,75=<b>34,3 g</b>.'),b('Disoluzioaren masa=2000·1,04=2080 g. Ezpurutasuna=34,33·0,25=8,58 g; CaCl₂=0,300·111=33,3 g; ura=2080−8,58−33,3=2038,1 g. Molalitatea=0,300/2,0381=<b>0,147 mol/kg</b>.','Masa de disolución=2000·1,04=2080 g. Impureza=34,33·0,25=8,58 g; CaCl₂=0,300·111=33,3 g; agua=2080−8,58−33,3=2038,1 g. Molalidad=0,300/2,0381=<b>0,147 mol/kg</b>.')],res:'34,3 g gatz komertzial; m≈0,147 mol/kg',check:b('C=0,300 mol/2,00 L=0,150 M. Disolbatzailearen masa osoa masaren balantzean aurkitzen da, gatz hidratatuaren ura barne.','C=0,300 mol/2,00 L=0,150 M. La masa total de disolvente se obtiene por balance de masas, incluido el agua del hidrato.'),errs:b('Gatz komertzialaren ezpurutasuna disoluzioaren masan sartu behar da, baina ez solutu aktiboaren mol-kopuruan.','La impureza de pureza forma parte de la masa de disolución, pero no de los moles de soluto activo.'),rubric:b('Molen balantzea 30 % · purutasuna zuzen aplikatzea 25 % · dentsitatea eta ur-masa 25 % · molalitatea eta unitateak 20 %.','Balance de moles 30 % · aplicar correctamente pureza 25 % · densidad y masa de agua 25 % · molalidad y unidades 20 %.')},
 {id:'O-07',lvl:2,skill:b('Nahaste ionikoen bi urratsak','Dos pasos de mezclas iónicas'),title:b('Kloruro-kontzentrazioaren mol-balantzea','Balance molar de concentración de cloruro'),q:b('150,0 mL 0,200 M NaCl eta 250,0 mL 0,120 M CaCl₂ nahastu dira. Bolumenak gehigarriak dira eta gatzak guztiz disoziatzen dira. Aurkitu [Na⁺], [Ca²⁺] eta [Cl⁻].','Se mezclan 150,0 mL de NaCl 0,200 M y 250,0 mL de CaCl₂ 0,120 M. Los volúmenes son aditivos y las sales se disocian completamente. Halla [Na⁺], [Ca²⁺] y [Cl⁻].'),parts:[{q:'[Na⁺] (M)',ans:.075,tol:.01},{q:'[Ca²⁺] (M)',ans:.075,tol:.01},{q:'[Cl⁻] (M)',ans:.225,tol:.01}],hints:[b('Lehenengo urratsa: gatz-molak n=CV.','Primer paso: moles de sal con n=CV.'),b('Cl⁻-ren molak NaCl-tik bat eta CaCl₂-tik bi dira.','Los moles de Cl⁻ son uno por NaCl y dos por CaCl₂.'),b('Azken bolumena 0,4000 L da.','El volumen final es 0,4000 L.')],sol:[b('n(NaCl)=0,200·0,1500=0,0300 mol; n(CaCl₂)=0,120·0,2500=0,0300 mol; Vtot=0,4000 L.','n(NaCl)=0,200·0,1500=0,0300 mol; n(CaCl₂)=0,120·0,2500=0,0300 mol; Vtot=0,4000 L.'),b('Na⁺=0,0300 mol, Ca²⁺=0,0300 mol, Cl⁻=0,0300+2·0,0300=0,0900 mol.','Na⁺=0,0300 mol, Ca²⁺=0,0300 mol, Cl⁻=0,0300+2·0,0300=0,0900 mol.'),b('Kontzentrazioak Vtot-z zatituz: <b>0,0750 M; 0,0750 M; 0,225 M</b>.','Al dividir entre Vtot: <b>0,0750 M; 0,0750 M; 0,225 M</b>.')],res:'[Na⁺]=0,0750 M; [Ca²⁺]=0,0750 M; [Cl⁻]=0,225 M',check:b('Karga: 0,0750+2(0,0750)=0,225 mol/L = [Cl⁻].','Carga: 0,0750+2(0,0750)=0,225 mol/L = [Cl⁻].'),errs:b('CaCl₂-k Cl⁻ mol bi ematen dituela ahaztea.','Olvidar que cada CaCl₂ aporta dos moles de Cl⁻.'),rubric:b('Mol-balantzea 35 % · ioi-koefizienteak 30 % · bolumen osoa 20 % · karga-egiaztapena 15 %.','Balance de moles 35 % · coeficientes iónicos 30 % · volumen total 20 % · comprobación de carga 15 %.')},
 {id:'O-08',lvl:2,skill:b('Gas aseak eta bolumen-%','Gas saturado y porcentaje en volumen'),title:b('Airea garbitu ondoren','Después de retirar componentes del aire'),q:b('Hasieran gas nahasteak 0,200 atm-ko PT du 20 °C-an, % 18 CO, % 2 O₂ eta ur-lurrun asearekin (P*H₂O=17,5 mmHg); gainerakoa N₂ da. O₂ eta H₂O erabat kentzen dira. Geratzen den gas lehorraren % bolumena CO/N₂ kalkulatu.','Una mezcla gaseosa está inicialmente a PT=0,200 atm y 20 °C, con 18 % CO, 2 % O₂ y vapor de agua saturado (P*H₂O=17,5 mmHg); el resto es N₂. Se retiran por completo O₂ y H₂O. Calcula los porcentajes en volumen de CO y N₂ del gas seco restante.'),parts:[{q:'CO (vol %)',ans:20.81,tol:.01},{q:'N₂ (vol %)',ans:79.19,tol:.01}],hints:[b('P(H₂O)=17,5/760 atm; kalkulatu mol-frakzioa PT-rekin zatituz.','P(H₂O)=17,5/760 atm; calcula su fracción molar dividiendo por PT.'),b('Hasierako CO eta N₂ mol-proportzioak mantendu.','Conserva la proporción molar inicial entre CO y N₂.')],sol:[b('y(H₂O)=(17,5/760)/0,200=0,1151. Beraz y(N₂)=1−0,18−0,02−0,1151=0,6849.','y(H₂O)=(17,5/760)/0,200=0,1151. Así y(N₂)=1−0,18−0,02−0,1151=0,6849.'),b('O₂ eta H₂O kenduta, CO=0,18 eta N₂=0,6849 unitate-mol proportzioan. Mol lehorrak guztira=0,8649.','Al retirar O₂ y H₂O, quedan proporciones de moles CO=0,18 y N₂=0,6849. Moles secos totales=0,8649.'),b('CO %=0,18/0,8649·100=<b>20,81 %</b>; N₂ %=0,6849/0,8649·100=<b>79,19 %</b>.','CO %=0,18/0,8649·100=<b>20,81 %</b>; N₂ %=0,6849/0,8649·100=<b>79,19 %</b>.')],res:'CO 20,81 %; N₂ 79,19 %',check:b('Gas lehorraren mol-frakzioak 1 dira; ur-lurrunaren presio partziala PT baino txikiagoa da.','Las fracciones molares del gas seco suman 1; la presión parcial del vapor es menor que PT.'),errs:b('Ur-lurrun asearen presio partziala lehen urratsean baztertzea.','Ignorar la presión parcial del vapor saturado en el primer paso.'),rubric:b('Ur-lurrunaren frakzioa 35 % · N₂-ren hasierako zatia 25 % · gas lehorra normalizatu 25 % · egiaztapena 15 %.','Fracción de vapor de agua 35 % · cantidad inicial de N₂ 25 % · normalizar gas seco 25 % · comprobación 15 %.')},
 {id:'O-09',lvl:3,skill:b('Purutasuna, mugatzailea eta errendimendua','Pureza, limitante y rendimiento'),title:b('Burdin(III) oxidoaren erredukzioa','Reducción de óxido de hierro(III)'),q:b('Fe₂O₃ + 3CO → 2Fe + 3CO₂. 16,0 g Fe₂O₃ laginak % 80 purutasuna du; 8,00 g CO eta 7,00 g Fe lortzen dira. M(Fe₂O₃)=159,69; M(CO)=28,01; M(Fe)=55,85 g/mol. Kalkulatu mugatzailea, Fe-ren etekin teorikoa eta ehuneko errendimendua.','Fe₂O₃ + 3CO → 2Fe + 3CO₂. Una muestra de 16,0 g de Fe₂O₃ tiene 80 % de pureza; hay 8,00 g de CO y se obtienen 7,00 g de Fe. M(Fe₂O₃)=159,69; M(CO)=28,01; M(Fe)=55,85 g/mol. Calcula el limitante, el rendimiento teórico de Fe y el porcentaje de rendimiento.'),parts:[{q:b('Mugatzailea: 1 Fe₂O₃ edo 2 CO','Limitante: 1 Fe₂O₃ o 2 CO'),ans:1,abs:.01},{q:b('Fe etekin teorikoa (g)','Rendimiento teórico de Fe (g)'),ans:8.953,tol:.005},{q:b('Errendimendua (%)','Rendimiento (%)'),ans:78.183,tol:.005}],hints:[b('Masa purua = lagina × purutasun-frakzioa.','Masa pura = muestra × fracción de pureza.'),b('Erreaktibo mugatzailea n/koefiziente txikienarekin aurkitzen da.','El limitante es el que tiene menor n/coeficiente.'),b('Errendimendua benetakoa / teorikoa ×100 da.','El rendimiento es real / teórico ×100.')],sol:[b('m(Fe₂O₃ purua)=16,0·0,80=12,80 g; n=12,80/159,69=0,08016 mol. n(CO)=8,00/28,01=0,2856 mol.','m(Fe₂O₃ puro)=16,0·0,80=12,80 g; n=12,80/159,69=0,08016 mol. n(CO)=8,00/28,01=0,2856 mol.'),b('n/ν: Fe₂O₃=0,08016; CO=0,2856/3=0,0952 mol. Fe₂O₃ mugatzailea da.','n/ν: Fe₂O₃=0,08016; CO=0,2856/3=0,0952 mol. Fe₂O₃ es el limitante.'),b('n(Fe) teorikoa=2·0,08016=0,16032 mol; m=0,16032·55,85=<b>8,953 g</b>.','n(Fe) teórico=2·0,08016=0,16032 mol; m=0,16032·55,85=<b>8,953 g</b>.'),b('Errendimendua=7,00/8,953·100=<b>78,18 %</b>.','Rendimiento=7,00/8,953·100=<b>78,18 %</b>.')],res:'Fe₂O₃ mugatzailea; 8,953 g Fe teoriko; 78,18 %',check:b('CO beharrezkoa=3·0,08016=0,2405 mol=6,74 g, eskuragarri dauden 8,00 g baino gutxiago.','CO requerido=3·0,08016=0,2405 mol=6,74 g, menos que los 8,00 g disponibles.'),errs:b('Etekina kalkulatzean laginaren ezpurutasuna Fe₂O₃ moduan sartzea.','Contar la impureza de la muestra como Fe₂O₃ al calcular el rendimiento.'),rubric:b('Purutasuna aplikatzea 20 % · molak eta mugatzailea 30 % · produktu teorikoa 25 % · errendimendua eta koherentzia 25 %.','Aplicar pureza 20 % · moles y limitante 30 % · producto teórico 25 % · rendimiento y coherencia 25 %.')},
 {id:'O-10',lvl:3,skill:b('Frakzio molarra eta bolumen-ehunekoa','Fracción molar y porcentaje en volumen'),title:b('Etanola ur-disoluzioan (2019-20 ez-ohikoa, 10)','Etanol en disolución acuosa (2019-20 extraordinaria, 10)'),q:b('Ur-disoluzioan etanolaren frakzio molarra 0,050 da. 25 °C-an ρ(etanol)=0,789 g/mL eta ρ(disoluzioa)=0,987 g/mL dira; M(etanol)=46,1 eta M(H₂O)=18,0 g/mol. Kalkulatu etanolaren bolumen-ehunekoa disoluzioan.','La fracción molar de etanol en una disolución acuosa es 0,050. A 25 °C, ρ(etanol)=0,789 g/mL y ρ(disolución)=0,987 g/mL; M(etanol)=46,1 y M(H₂O)=18,0 g/mol. Calcula el porcentaje en volumen de etanol en la disolución.'),parts:[{q:'Etanol bolumen-%',ans:14.86,tol:.01}],hints:[b('Hartu 1 mol disoluzio: 0,050 mol etanol eta 0,950 mol ur.','Toma 1 mol de disolución: 0,050 mol de etanol y 0,950 mol de agua.'),b('Osagai bakoitzaren masa, likido-etanolaren bolumena eta disoluzioaren masa/bolumena kalkulatu.','Calcula las masas de ambos componentes, el volumen del etanol líquido y la masa/volumen de disolución.')],sol:[b('Etanol-masa=0,050·46,1=2,305 g; ur-masa=0,950·18,0=17,10 g. Disoluzio-masa=19,405 g.','Masa de etanol=0,050·46,1=2,305 g; masa de agua=0,950·18,0=17,10 g. Masa de disolución=19,405 g.'),b('Etanol-bolumena=2,305/0,789=2,921 mL; disoluzioaren bolumena=19,405/0,987=19,66 mL.','Volumen de etanol=2,305/0,789=2,921 mL; volumen de disolución=19,405/0,987=19,66 mL.'),b('% v/v=2,921/19,66·100=<b>14,86 %</b>.','% v/v=2,921/19,66·100=<b>14,86 %</b>.')],res:'Etanola = 14,86 % v/v',check:b('Bolumen-ehunekoa mol-frakzioa baino handiagoa da, etanolaren masa molarra urarena baino handiagoa delako eta haren dentsitatea txikiagoa delako.','El porcentaje en volumen supera la fracción molar porque la masa molar del etanol es mayor que la del agua y su densidad es menor.'),errs:b('Etanolaren frakzio molarra zuzenean bolumen-ehunekotzat hartzea.','Tomar directamente la fracción molar de etanol como porcentaje en volumen.'),rubric:b('Oinarri molarra 20 % · bi masak 20 % · dentsitate bidezko bi bolumenak 35 % · ehunekoa eta unitatea 25 %.','Base molar 20 % · ambas masas 20 % · ambos volúmenes con densidad 35 % · porcentaje y unidad 25 %.')}
];
