Object.assign(X.find(x=>x.id==='O-08'),{
 title:b('Gas aseko beste nahaste bat: osagaiak kentzea','Otra mezcla saturada: retirada de componentes'),
 q:b('Hasieran gas-nahaste batek PT=0,750 atm du 25 °C-an; % 12 CO, % 4 O₂ eta ur-lurrun aseak osatzen dute, P*(H₂O)=23,8 mmHg izanik. Gainerakoa N₂ da. O₂ eta H₂O guztiz kentzen dira. Kalkulatu geratzen den gas lehorreko CO eta N₂-ren bolumen-ehunekoak.','Una mezcla gaseosa está inicialmente a PT=0,750 atm y 25 °C; contiene 12 % de CO, 4 % de O₂ y vapor de agua saturado, con P*(H₂O)=23,8 mmHg. El resto es N₂. Se retiran por completo O₂ y H₂O. Calcula los porcentajes en volumen de CO y N₂ que quedan en el gas seco.'),
 parts:[{q:'CO (vol %)',ans:13.0684,tol:.005},{q:'N₂ (vol %)',ans:86.9316,tol:.005}],
 hints:[b('Asetasunean P(H₂O)=P*. Bihurtu mmHg atm-ra eta zatitu PT-z frakzio molarra lortzeko.','En saturación P(H₂O)=P*. Convierte mmHg a atm y divide por PT para hallar su fracción molar.'),b('Gas lehorraren mol-proportzioetan, mantendu CO-ren % 12 eta kendu O₂ zein H₂O.','En las proporciones de moles del gas seco, conserva el 12 % de CO y resta O₂ y H₂O.')],
 sol:[b('Ur-lurrunaren frakzio molarra: y(H₂O)=(23,8/760)/0,750=0,04175. Beraz y(N₂)=1−0,120−0,040−0,04175=0,79825.','Fracción molar del vapor: y(H₂O)=(23,8/760)/0,750=0,04175. Por tanto, y(N₂)=1−0,120−0,040−0,04175=0,79825.'),b('O₂ eta H₂O kenduta, CO eta N₂-ren mol-proportzioa 0,120:0,79825 da; guztira 0,91825 zati-mol.','Al retirar O₂ y H₂O, la proporción molar de CO y N₂ es 0,120:0,79825; quedan 0,91825 partes-mol.'),b('CO bolumen-% =0,120/0,91825·100=<b>13,07 %</b>; N₂ bolumen-% =0,79825/0,91825·100=<b>86,93 %</b>.','% en volumen de CO =0,120/0,91825·100=<b>13,07 %</b>; % en volumen de N₂ =0,79825/0,91825·100=<b>86,93 %</b>.')],
 res:'CO 13,07 %; N₂ 86,93 %',
 check:b('Gas lehorraren ehunekoak 100 dira. Ur-lurrunaren presio partziala 0,0313 atm da, PT baino txikiagoa.','Los porcentajes del gas seco suman 100. La presión parcial del vapor es 0,0313 atm, menor que PT.'),
 errs:b('P*(H₂O) zuzenean nahastearen frakzio gisa erabiltzea, PT-z zatitu gabe.','Usar P*(H₂O) directamente como fracción de la mezcla, sin dividir por PT.'),
 rubric:b('Asetasunetik uraren frakzioa 35 % · N₂ hasierakoa 25 % · gas lehorra berriz normalizatu 25 % · batura-egiaztapena 15 %.','Fracción de vapor por saturación 35 % · fracción inicial de N₂ 25 % · renormalización del gas seco 25 % · comprobación de la suma 15 %.')
});
